class AuthInterceptor(private val store: TokenStore) : Interceptor {
    override fun intercept(chain: Interceptor.Chain): Response {
        val token = store.accessToken
        val request = if (token != null) {
            chain.request().newBuilder().header("Authorization", "Bearer $token").build()
        } else chain.request()
        return chain.proceed(request)
    }
}

class TokenAuthenticator(
    private val store: TokenStore,
    private val refreshApi: RefreshApi,
) : Authenticator {

    private val mutex = Mutex()

    override fun authenticate(route: Route?, response: Response): Request? {
        // Give up rather than loop forever
        if (response.priorResponseCount() >= 2) return null

        val failedToken = response.request.header("Authorization")?.removePrefix("Bearer ")

        val newToken = runBlocking {
            mutex.withLock {
                // Another thread may already have refreshed while we waited
                val current = store.accessToken
                if (current != null && current != failedToken) return@withLock current
                refreshApi.refresh(store.refreshToken)
                    .also { store.save(it) }
                    .accessToken
            }
        } ?: return null

        return response.request.newBuilder()
            .header("Authorization", "Bearer $newToken")
            .build()
    }

    private fun Response.priorResponseCount(): Int {
        var count = 0; var r = priorResponse
        while (r != null) { count++; r = r.priorResponse }
        return count
    }
}

val MIGRATION_2_3 = object : Migration(2, 3) {
    override fun migrate(db: SupportSQLiteDatabase) {
        db.execSQL("ALTER TABLE users ADD COLUMN avatar_url TEXT")
        db.execSQL("CREATE INDEX IF NOT EXISTS index_users_team ON users(team_id)")
    }
}

// The test that keeps you honest
@RunWith(AndroidJUnit4::class)
class MigrationTest {
    @get:Rule
    val helper = MigrationTestHelper(
        InstrumentationRegistry.getInstrumentation(),
        AppDatabase::class.java
    )

    @Test
    fun migrate2To3() {
        helper.createDatabase(TEST_DB, 2).apply {
            execSQL("INSERT INTO users (id, name) VALUES ('1', 'Ada')")
            close()
        }
        val db = helper.runMigrationsAndValidate(TEST_DB, 3, true, MIGRATION_2_3)
        db.query("SELECT avatar_url FROM users WHERE id = '1'").use {
            assertTrue(it.moveToFirst())
        }
    }
}

private val Context.dataStore by preferencesDataStore(
    name = "settings",
    produceMigrations = { ctx -> listOf(SharedPreferencesMigration(ctx, "legacy_prefs")) }
)

class SettingsRepository(private val context: Context) {

    private val darkModeKey = booleanPreferencesKey("dark_mode")

    val darkMode: Flow<Boolean> = context.dataStore.data
        .catch { e ->
            // A corrupt file should degrade to defaults, not crash the app
            if (e is IOException) emit(emptyPreferences()) else throw e
        }
        .map { it[darkModeKey] ?: false }

    suspend fun setDarkMode(enabled: Boolean) {
        context.dataStore.edit { it[darkModeKey] = enabled }   // atomic
    }
}

@OptIn(ExperimentalPagingApi::class)
class FeedRemoteMediator(
    private val db: AppDatabase,
    private val api: FeedApi,
) : RemoteMediator<Int, PostEntity>() {

    override suspend fun load(loadType: LoadType, state: PagingState<Int, PostEntity>): MediatorResult {
        return try {
            val cursor: String? = when (loadType) {
                LoadType.REFRESH -> null
                LoadType.PREPEND -> return MediatorResult.Success(endOfPaginationReached = true)
                LoadType.APPEND -> db.remoteKeyDao().cursor("feed")
                    ?: return MediatorResult.Success(endOfPaginationReached = true)
            }

            val response = api.feed(cursor = cursor, limit = state.config.pageSize)

            db.withTransaction {                                  // atomic: rows + cursor together
                if (loadType == LoadType.REFRESH) {
                    db.postDao().clearAll()
                    db.remoteKeyDao().clear("feed")
                }
                db.postDao().insertAll(response.items.map { it.toEntity() })
                db.remoteKeyDao().upsert(RemoteKey("feed", response.nextCursor))
            }

            MediatorResult.Success(endOfPaginationReached = response.nextCursor == null)
        } catch (e: IOException) {
            MediatorResult.Error(e)
        } catch (e: HttpException) {
            MediatorResult.Error(e)
        }
    }
}
